import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import { SignupForm } from "../src/SignupForm";

function deferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((res) => {
    resolve = res;
  });
  return { promise, resolve };
}

async function fillValidForm() {
  const user = userEvent.setup();
  await user.type(screen.getByLabelText("Email"), "jane@example.com");
  await user.type(screen.getByLabelText("Password"), "correct horse battery");
  await user.type(screen.getByLabelText("Confirm password"), "correct horse battery");
  return user;
}

describe("SignupForm", () => {
  it("shows the email error on blur and wires aria-describedby / aria-invalid", async () => {
    render(<SignupForm onSubmit={vi.fn()} />);
    const user = userEvent.setup();

    const email = screen.getByRole("textbox", { name: "Email" });
    expect(email).not.toHaveAttribute("aria-invalid");

    await user.type(email, "not-an-email");
    // No error before blur.
    expect(screen.queryByRole("alert")).toBeNull();

    email.blur();
    expect(await screen.findByText("Enter a valid email address.")).toBeInTheDocument();

    expect(email).toHaveAttribute("aria-invalid", "true");
    expect(email).toHaveAccessibleDescription("Enter a valid email address.");

    const describedBy = email.getAttribute("aria-describedby")!;
    expect(describedBy).toBeTruthy();
    expect(document.getElementById(describedBy)).toHaveTextContent(
      "Enter a valid email address."
    );
  });

  it("validates password length on blur", async () => {
    render(<SignupForm onSubmit={vi.fn()} />);
    const user = userEvent.setup();

    const password = screen.getByLabelText("Password");
    await user.type(password, "short");
    password.blur();

    expect(await screen.findByText("Password must be at least 8 characters.")).toBeInTheDocument();
    expect(password).toHaveAttribute("aria-invalid", "true");
  });

  it("blocks submit when confirm does not match and reports the mismatch", async () => {
    const onSubmit = vi.fn().mockResolvedValue(undefined);
    render(<SignupForm onSubmit={onSubmit} />);
    const user = userEvent.setup();

    await user.type(screen.getByRole("textbox", { name: "Email" }), "jane@example.com");
    await user.type(screen.getByLabelText("Password"), "longenough123");
    await user.type(screen.getByLabelText("Confirm password"), "different456");

    await user.click(screen.getByRole("button", { name: "Sign up" }));

    expect(
      await screen.findByText("Passwords do not match.")
    ).toBeInTheDocument();
    expect(onSubmit).not.toHaveBeenCalled();
  });

  it("disables the submit button while onSubmit is pending and resets the form on success", async () => {
    const d = deferred<{ ok: true }>();
    const onSubmit = vi.fn().mockReturnValue(d.promise);
    render(<SignupForm onSubmit={onSubmit} />);
    const user = await fillValidForm();

    await user.click(screen.getByRole("button", { name: "Sign up" }));
    expect(onSubmit).toHaveBeenCalledWith({
      email: "jane@example.com",
      password: "correct horse battery",
    });

    const submittingButton = screen.getByRole("button", { name: /signing up/i });
    expect(submittingButton).toBeDisabled();

    d.resolve({ ok: true });

    // Back to enabled, success state.
    expect(await screen.findByRole("button", { name: "Sign up" })).toBeEnabled();

    // Form was reset.
    expect(screen.getByRole("textbox", { name: "Email" })).toHaveValue("");
    expect(screen.getByLabelText("Password")).toHaveValue("");
    expect(screen.getByLabelText("Confirm password")).toHaveValue("");
  });
});

